// stripeService.js - COMPLETAMENTE DESACTIVADO
console.log('🧪 Stripe Service: MODO PRUEBA ACTIVADO - Stripe desactivado');

const stripeService = {
  createConnectAccount: async (email, nombre, pais) => {
    console.log('🧪 Mock: createConnectAccount', email);
    return { accountId: 'mock_account_' + Date.now() };
  },
  
  getOnboardingStatus: async () => {
    console.log('🧪 Mock: getOnboardingStatus');
    return {
      hasStripeAccount: true,
      onboardingCompleted: true,
      payoutsEnabled: true,
      chargesEnabled: true
    };
  },
  
  createPaymentIntent: async (amount, currency) => {
    console.log('🧪 Mock: createPaymentIntent', amount, currency);
    return { clientSecret: 'mock_secret_' + Date.now() };
  },
  
  getPublishableKey: () => {
    console.log('🧪 Mock: getPublishableKey');
    return null;
  },
  
  // Método para inicializar Stripe (no hace nada)
  initStripe: () => {
    console.log('🧪 Mock: initStripe - Stripe desactivado');
    return null;
  }
};

export default stripeService;
